+const menuToggle = document.querySelector(".menu-toggle");
+const navLinks = document.querySelector(".nav-links");
+const cartCount = document.querySelector("#cart-count");
+const addToCartButtons = document.querySelectorAll(".add-to-cart");
+const countdown = document.querySelector("#countdown");
+const signupForm = document.querySelector("#signup-form");
+const formMessage = document.querySelector("#form-message");
+
+let cartItems = 0;
+
+menuToggle.addEventListener("click", () => {
+  const isOpen = navLinks.classList.toggle("is-open");
+  document.body.classList.toggle("menu-open", isOpen);
+  menuToggle.setAttribute("aria-expanded", String(isOpen));
+});
+
+navLinks.addEventListener("click", (event) => {
+  if (event.target.tagName === "A") {
+    navLinks.classList.remove("is-open");
+    document.body.classList.remove("menu-open");
+    menuToggle.setAttribute("aria-expanded", "false");
+  }
+});
+
+addToCartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    cartItems += 1;
+    cartCount.textContent = cartItems;
+    button.textContent = "Added";
+    button.disabled = true;
+
+    window.setTimeout(() => {
+      button.textContent = "Add to cart";
+      button.disabled = false;
+    }, 1100);
+  });
+});
+
+function updateCountdown() {
+  const endDate = new Date();
+  endDate.setDate(endDate.getDate() + 5);
+  endDate.setHours(23, 59, 59, 999);
+
+  const now = new Date();
+  const distance = Math.max(0, endDate - now);
+  const parts = [
+    Math.floor(distance / (1000 * 60 * 60 * 24)),
+    Math.floor((distance / (1000 * 60 * 60)) % 24),
+    Math.floor((distance / (1000 * 60)) % 60),
+    Math.floor((distance / 1000) % 60),
+  ];
+
+  countdown.querySelectorAll("strong").forEach((element, index) => {
+    element.textContent = String(parts[index]).padStart(2, "0");
+  });
+}
+
+signupForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const email = new FormData(signupForm).get("email");
+  formMessage.textContent = `Thanks, ${email}. Your welcome offer is on the way.`;
+  signupForm.reset();
+});
+
+updateCountdown();
+window.setInterval(updateCountdown, 1000);
