  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 28px;
}

.brand,
.nav-links,
.nav-actions,
.hero-actions,
.product-info,
.section-heading,
.countdown,
.site-footer,
.footer-links {
  display: flex;
  align-items: center;
}

.brand {
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--ink);
  color: var(--cream);
  letter-spacing: -0.08em;
}

.nav-links {
  justify-content: center;
  gap: 26px;
  color: var(--muted);
  font-size: 0.94rem;
  font-weight: 600;
}

.nav-links a {
