}

.nav-links a:hover {
  color: var(--ink);
}

.nav-actions {
  gap: 10px;
  justify-content: flex-end;
}

.icon-button,
.cart-button,
.menu-toggle {
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
}

.icon-button {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
}

.icon-button svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
}

.cart-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 16px;
  border-radius: 999px;
  font-weight: 700;
}

.cart-count {
  display: grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--paper);
  font-size: 0.78rem;
}

.menu-toggle {
  display: none;
  width: 42px;
  height: 42px;
  border-radius: 50%;
}

.menu-toggle span:not(.sr-only) {
  display: block;
  width: 18px;
  height: 2px;
  margin: 4px auto;
  border-radius: 99px;
  background: var(--ink);
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, 0.82fr);
  gap: 44px;
  align-items: center;
  min-height: 720px;
  padding-top: 72px;
  padding-bottom: 72px;
}

.eyebrow {
  margin: 0 0 14px;
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  max-width: 760px;
  margin-bottom: 22px;
  font-size: clamp(3rem, 8vw, 6.8rem);
  line-height: 0.9;
  letter-spacing: -0.085em;
}

h2 {
  margin-bottom: 0;
  font-size: clamp(2rem, 4vw, 3.45rem);
  line-height: 1;
  letter-spacing: -0.07em;
}

h3 {
  margin-bottom: 8px;
  letter-spacing: -0.035em;
}

.hero-copy {
  max-width: 600px;
  color: var(--muted);
  font-size: clamp(1rem, 2vw, 1.2rem);
  line-height: 1.75;
}

.hero-actions {
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 34px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 50px;
  padding: 0 22px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.button:hover,
.product-card:hover,
.article-card:hover {
  transform: translateY(-3px);
}

.button-primary {
  background: var(--ink);
  color: var(--paper);
  box-shadow: 0 14px 34px rgba(21, 21, 19, 0.18);
}

.button-secondary {
  background: var(--paper);
  border-color: var(--line);
}

.hero-showcase {
  position: relative;
}

.showcase-card {
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: var(--paper);
  box-shadow: var(--shadow);
}

.showcase-main {
  position: relative;
  min-height: 570px;
}

.showcase-main img {
  width: 100%;
  height: 570px;
  object-fit: cover;
}

.showcase-main::after {
  position: absolute;
  inset: 0;
  content: "";
  background: linear-gradient(180deg, transparent 48%, rgba(0, 0, 0, 0.68));
}

.showcase-main div {
  position: absolute;
  right: 24px;
  bottom: 24px;
  left: 24px;
  z-index: 1;
  color: var(--paper);
}

.showcase-main span,
.showcase-small span,
.mini-deal span,
.article-card span {
  display: block;
  margin-bottom: 8px;
  color: inherit;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.showcase-main strong {
  display: block;
  font-size: 2.2rem;
  letter-spacing: -0.06em;
}

.showcase-small {
  position: absolute;
  right: -18px;
  bottom: 44px;
  width: 210px;
  padding: 24px;
  background: var(--accent);
  color: var(--paper);
}

.showcase-small p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.82);
}

.category-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  overflow: hidden;
  margin-bottom: 94px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--line);
}

.category-strip a {
  padding: 24px;
  background: var(--paper);
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.category-strip span {
  display: block;
  margin-bottom: 26px;
  color: var(--muted);
  font-size: 0.8rem;
}

.section-heading {
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 30px;
}

.text-link {
  color: var(--muted);
  font-weight: 800;
  border-bottom: 1px solid currentColor;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}

.product-card,
.article-card,
.deal-card,
.mini-deal,
.membership {
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--paper);
}

.product-card,
.article-card {
  overflow: hidden;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.product-card:hover,
.article-card:hover {
  box-shadow: var(--shadow);
}

.product-media {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 1 / 1.08;
  overflow: hidden;
}

.product-media img {
  width: 86%;
  height: 86%;
  object-fit: cover;
  border-radius: 24px;
  mix-blend-mode: multiply;
}

.product-media.clay {
  background: #efd8cc;
}

.product-media.sage {
  background: #dbe4d5;
}

.product-media.oat {
  background: #f1e3cf;
}

.product-media.charcoal {
  background: #d7d2cc;
}

.badge {
  position: absolute;
  top: 16px;
  left: 16px;
  z-index: 1;
  padding: 7px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.82);
  font-size: 0.72rem;
  font-weight: 800;
}

.product-info {
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 18px 18px 12px;
}

.product-info p {
  margin-bottom: 0;
  color: var(--muted);
  font-size: 0.92rem;
}

.product-info strong {
  white-space: nowrap;
}

.add-to-cart {
  width: calc(100% - 36px);
  margin: 0 18px 18px;
  min-height: 44px;
  border: 0;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  font-weight: 800;
  cursor: pointer;
}

.deals {
