}

.primary-deal p:not(.eyebrow) {
  max-width: 650px;
  color: var(--muted);
  line-height: 1.75;
}

.countdown {
  flex-wrap: wrap;
  gap: 10px;
  margin: 28px 0;
}

.countdown span {
  min-width: 92px;
  padding: 14px;
  border-radius: var(--radius-sm);
  background: var(--cream);
  color: var(--muted);
  font-size: 0.76rem;
  font-weight: 800;
  text-transform: uppercase;
}

.countdown strong {
  display: block;
  color: var(--ink);
  font-size: 1.6rem;
}

.deal-stack {
  display: grid;
  gap: 22px;
}

.mini-deal {
  min-height: 190px;
  background: var(--sage);
}

.mini-deal.dark {
  background: var(--ink);
  color: var(--paper);
}

.mini-deal h3 {
  margin-bottom: 0;
  font-size: 1.55rem;
  line-height: 1.12;
}

.editorial {
  padding-bottom: 108px;
}

.article-grid {
  display: grid;
  grid-template-columns: 1.25fr 0.875fr 0.875fr;
  gap: 22px;
}

.article-card img {
  width: 100%;
  height: 230px;
  object-fit: cover;
}

.feature-article img {
  height: 420px;
}

.article-card div {
  padding: 22px;
}

.article-card span {
  color: var(--accent);
}

.article-card p {
  margin-bottom: 0;
  color: var(--muted);
  line-height: 1.65;
}

.membership {
  display: grid;
  grid-template-columns: 1fr minmax(320px, 0.85fr);
  gap: 28px;
  align-items: center;
  margin-bottom: 86px;
  background: var(--charcoal);
  color: var(--paper);
}

.membership .eyebrow {
  color: #ffb18a;
}

.signup-form {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
}

.signup-form input {
  min-height: 54px;
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  padding: 0 18px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--paper);
}

.signup-form input::placeholder {
  color: rgba(255, 255, 255, 0.62);
}

.form-message {
  grid-column: 1 / -1;
  min-height: 20px;
  margin: 0;
  color: #ffcfb8;
  font-size: 0.9rem;
}

.site-footer {
  justify-content: space-between;
  gap: 28px;
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 34px 0 46px;
  border-top: 1px solid var(--line);
}

.site-footer p {
  margin: 12px 0 0;
  color: var(--muted);
}

.footer-links {
  flex-wrap: wrap;
  gap: 18px;
  color: var(--muted);
  font-weight: 700;
}

@media (max-width: 980px) {
  .navbar {
    grid-template-columns: auto auto 1fr;
  }

  .menu-toggle {
    display: block;
  }

  .nav-links {
    position: fixed;
    top: 74px;
    right: 20px;
    left: 20px;
    display: none;
    flex-direction: column;
    align-items: stretch;
    padding: 18px;
    border: 1px solid var(--line);
    border-radius: var(--radius-md);
    background: var(--paper);
    box-shadow: var(--shadow);
  }

  .nav-links.is-open {
    display: flex;
  }

  .hero,
  .deals,
  .membership {
    grid-template-columns: 1fr;
  }

  .hero {
    min-height: auto;
  }

  .product-grid,
  .category-strip {
    grid-template-columns: repeat(2, 1fr);
  }

  .article-grid {
    grid-template-columns: 1fr;
  }

  .feature-article img,
  .article-card img {
    height: 320px;
  }
}

@media (max-width: 640px) {
  .section-pad,
  .navbar,
  .site-footer {
    width: min(100% - 28px, 1180px);
  }

  .navbar {
    gap: 12px;
  }

  .brand span:last-child {
    display: none;
  }

  .nav-actions .icon-button {
    display: none;
  }

  .hero {
    padding-top: 44px;
    padding-bottom: 54px;
  }

  .hero-showcase {
    margin-right: 0;
  }

  .showcase-main,
  .showcase-main img {
    min-height: 430px;
    height: 430px;
  }

  .showcase-small {
    right: 12px;
    bottom: 16px;
  }

  .category-strip,
  .product-grid,
  .signup-form {
    grid-template-columns: 1fr;
  }

  .section-heading,
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
  }
}
